import { useCallback, useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  defaultTags?: string[];
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({ defaultTags = [], onChange }: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultTags);

  const updateTags = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange]
  );

  const removeTag = useCallback(
    (tag: string) => {
      updateTags(tags.filter((t) => t !== tag));
    },
    [tags, updateTags]
  );

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={updateTags}
      />

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        <span style={{ fontFamily: 'var(--jx-font-body)', color: 'var(--jx-color-text-muted)' }}>
          Выбранные теги
        </span>

        {tags.length === 0 ? (
          <span style={{ fontFamily: 'var(--jx-font-body)', color: 'var(--jx-color-text-muted)' }}>
            Теги ещё не добавлены
          </span>
        ) : (
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
            {tags.map((tag) => (
              <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
                {tag}
              </JxChip>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

